{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": [
    "C01","C02","C10","C22","C24","C13","C07","C03","C09","C08","C12",
    "C05","C23","C25","C06","C14","C04","C11","C21","C33","C34","C27",
    "C31","C26","C35","C36","C37","C28"
  ],
  "contradictory_card_ids": ["C29","C30","C32"],
  "prediction_basis_card_ids": [
    "C01","C02","C10","C22","C24","C13","C07","C03","C09","C08","C12",
    "C05","C23","C25","C06","C14","C04","C11","C21"
  ],
  "claims": [
    {
      "claim": "Fenspiride, the closest spiro oxa-aza structural context, had absolute oral bioavailability of 90% in healthy volunteers, directly supporting F >= 20%.",
      "card_ids": ["C01","C02"]
    },
    {
      "claim": "PF-592379, a small basic amine with an ether-containing saturated heterocycle, had predicted human F >60%, dog F 61%, and rat F 28%, all at or above the 20% threshold.",
      "card_ids": ["C10","C22","C24"]
    },
    {
      "claim": "Other small basic amine contexts report F at or above 20%: nicotine 44%, diltiazem 38 ± 11%, nalmefene 53%, levofloxacin approaching 100%, vicriviroc excellent, and tacrolimus/TDP223206 20–33%.",
      "card_ids": ["C13","C07","C03","C09","C08","C12","C05","C23","C25"]
    },
    {
      "claim": "Pethidine and pentazocine F values of 0.80 and 0.68–0.70 were measured in cirrhosis, where reduced first-pass metabolism increases F; these are less transferable to a healthy query but are not evidence of low F.",
      "card_ids": ["C06","C14","C04","C11","C16","C18","C17","C20"]
    },
    {
      "claim": "L3 oral exposure records show measurable Cmax/AUC after oral dosing for dextromethorphan, gepirone, morphine, hydromorphone, and 6-β-naloxole, consistent with oral absorption, but they lack IV-reference F values and are not direct F evidence.",
      "card_ids": ["C26","C27","C28","C31","C33","C34","C35","C36","C37"]
    },
    {
      "claim": "Naloxone oral Cmax values are very low (0.07–29 pg/mL), but naloxone is structurally distinct (morphinan with phenol/ketone) and this low-exposure context has limited transferability to the query's spiro THF-piperidine.",
      "card_ids": ["C29","C30","C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "No IV-reference AUC or F calculation is available for the query or for the L3 reference molecules.",
    "L3 Cmax/AUC values are not dose-normalized and lack comparator exposure, so they cannot establish the F >= 20% threshold.",
    "The low oral Cmax of naloxone is of limited transferability because the query lacks the phenolic/ketone motifs of naloxone; no close low-F analog is present.",
    "First-pass metabolism of the exocyclic methylene and tertiary amine, and the effect of high ionization (pKa 9.58, logD -0.37) on permeability, are not directly characterized.",
    "Species differences and close-to-threshold values (PF-592379 rat 28%, tacrolimus/TDP223206 20–33%) leave residual uncertainty."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the closest structural context fenspiride (90%) and the small basic amine PF-592379 (28–61%) support F at or above threshold, and no transferable affirmative low-F evidence exists. L3 oral exposure records are indirect Cmax/AUC data without IV-reference F values; the low naloxone Cmax is structurally distant and does not overturn the prior. Confidence remains moderate due to lack of direct query PK."
}

